-- The Dash: complete database setup for a NEW, empty Supabase project.
-- Generated by scripts/bundle-migrations.mjs. Paste into Supabase > SQL Editor and click Run.

begin;

create table if not exists _dash_migrations (name text primary key, applied_at timestamptz not null default now());

-- ── 20261118000001_init.sql ──
-- The Dash: milestone 1 schema.
-- RLS is enabled on every table with NO policies: the Supabase anon/authenticated
-- roles (PostgREST) can read or write nothing. All access goes through the
-- Next.js server using the database connection string.

create extension if not exists pgcrypto;

create type entry_kind as enum ('observation', 'journal', 'voice_note', 'quote', 'question', 'reading');
create type entry_stage as enum ('seed', 'sprouting', 'ready', 'used');
create type issue_status as enum ('draft', 'approved', 'published');

-- Raw material: the author's own observations, experiences and notes.
create table entries (
  id          uuid primary key default gen_random_uuid(),
  kind        entry_kind  not null default 'observation',
  body        text        not null check (length(body) between 1 and 20000),
  pillar      text        not null default 'Philosophy',
  stage       entry_stage not null default 'seed',
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create index entries_created_at_idx on entries (created_at desc);

create table issues (
  id            uuid primary key default gen_random_uuid(),
  number        integer      not null unique,
  slug          text         not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  status        issue_status not null default 'draft',
  subject       text         not null default '',
  preview       text         not null default '',
  title         text         not null default '',
  opening       text         not null default '',
  body          jsonb        not null default '{"type":"doc","content":[]}'::jsonb,
  learning      text         not null default '',
  links         jsonb        not null default '[]'::jsonb,
  question      text         not null default '',
  approved_at   timestamptz,
  published_at  timestamptz,
  created_at    timestamptz  not null default now(),
  updated_at    timestamptz  not null default now(),
  -- Human approval is required before anything is published.
  constraint published_requires_approval check (status <> 'published' or (approved_at is not null and published_at is not null))
);
create index issues_published_idx on issues (published_at desc) where status = 'published';

-- Which captured entries an issue was built from (provenance: never invent experiences).
create table issue_sources (
  issue_id  uuid not null references issues (id) on delete cascade,
  entry_id  uuid not null references entries (id) on delete cascade,
  primary key (issue_id, entry_id)
);

create or replace function touch_updated_at() returns trigger language plpgsql as $$
begin new.updated_at = now(); return new; end $$;

create trigger entries_touch before update on entries for each row execute function touch_updated_at();
create trigger issues_touch  before update on issues  for each row execute function touch_updated_at();

alter table entries       enable row level security;
alter table issues        enable row level security;
alter table issue_sources enable row level security;

insert into _dash_migrations (name) values ('20261118000001_init.sql');

-- ── 20261119000001_subscribers.sql ──
-- The Dash: milestone 2 (subscribers and sending).
-- Same rule as before: RLS enabled, no policies; only the server touches these tables.

create extension if not exists citext;

create type subscriber_status as enum ('pending', 'active', 'unsubscribed', 'bounced', 'complained');

create table subscribers (
  id                  uuid primary key default gen_random_uuid(),
  email               citext not null unique check (length(email) <= 254 and email ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
  name                text   not null default '' check (length(name) <= 100),
  status              subscriber_status not null default 'pending',
  -- Consent record: how and when they agreed.
  consent_source      text   not null check (consent_source in ('web_form', 'personal_invite', 'import')),
  consent_at          timestamptz,
  -- Double opt-in: only a SHA-256 hash of the confirmation token is stored.
  confirm_token_hash  text unique,
  confirm_expires_at  timestamptz,
  confirm_sent_at     timestamptz,
  unsubscribed_at     timestamptz,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  constraint active_requires_consent check (status <> 'active' or consent_at is not null)
);
create index subscribers_status_idx on subscribers (status);
create trigger subscribers_touch before update on subscribers for each row execute function touch_updated_at();

-- Owner test sends must happen after the latest approval before a real send is allowed.
alter table issues add column test_sent_at timestamptz;

create type send_status as enum ('sending', 'sent', 'partial');

-- One real send per issue, ever.
create table sends (
  id            uuid primary key default gen_random_uuid(),
  issue_id      uuid not null unique references issues (id) on delete restrict,
  status        send_status not null default 'sending',
  recipients    integer not null,
  confirmed_at  timestamptz not null,
  completed_at  timestamptz,
  created_at    timestamptz not null default now()
);

create type delivery_status as enum ('queued', 'sent', 'failed', 'delivered', 'bounced', 'complained');

create table deliveries (
  id             uuid primary key default gen_random_uuid(),
  send_id        uuid not null references sends (id) on delete cascade,
  subscriber_id  uuid not null references subscribers (id) on delete cascade,
  status         delivery_status not null default 'queued',
  provider_id    text unique,
  error          text,
  updated_at     timestamptz not null default now(),
  unique (send_id, subscriber_id)
);
create index deliveries_queued_idx on deliveries (send_id) where status = 'queued';
create trigger deliveries_touch before update on deliveries for each row execute function touch_updated_at();

-- Fixed-window rate limiting for public endpoints (keys are hashed).
create table rate_limits (
  key           text primary key,
  window_start  timestamptz not null,
  hits          integer not null
);

-- Processed webhook ids, so retries are idempotent.
create table webhook_events (
  id           text primary key,
  type         text not null,
  received_at  timestamptz not null default now()
);

alter table subscribers    enable row level security;
alter table sends          enable row level security;
alter table deliveries     enable row level security;
alter table rate_limits    enable row level security;
alter table webhook_events enable row level security;

insert into _dash_migrations (name) values ('20261119000001_subscribers.sql');

-- ── 20261120000001_knowledge.sql ──
-- Personal Knowledge & Reflection System, phase 1.
-- Private by default: RLS on, no policies; only the authenticated server reads or writes.

create type capture_kind as enum ('thought', 'quote', 'book', 'film', 'social_post', 'conversation', 'experience', 'journal', 'other');
create type text_origin  as enum ('human', 'ai');

-- One captured item. The ORIGINAL material, its PROVENANCE and Col's REACTION are kept in separate
-- fields so third-party words are never confused with Col's own thinking.
create table captures (
  id             uuid primary key default gen_random_uuid(),
  kind           capture_kind not null default 'thought',
  title          text not null default '' check (length(title) <= 300),
  -- Original source material, verbatim (a quote, a post, a passage). May be empty for a pure thought.
  content        text not null default '' check (length(content) <= 50000),
  -- Provenance
  source_url     text check (source_url is null or (length(source_url) <= 2000 and source_url ~* '^https?://')),
  attribution    text not null default '' check (length(attribution) <= 300),  -- who said/wrote/made it
  source_title   text not null default '' check (length(source_title) <= 300), -- book, film, account, place
  source_locator text not null default '' check (length(source_locator) <= 200),-- page, timestamp, chapter
  occurred_at    timestamptz,                                                   -- when it was read/heard/happened
  -- Col's own words
  reaction       text not null default '' check (length(reaction) <= 50000),
  -- Derived text, editable, with origin so AI text is never mistaken for Col's
  transcript         text not null default '' check (length(transcript) <= 100000),
  transcript_origin  text_origin,
  summary            text not null default '' check (length(summary) <= 5000),
  summary_origin     text_origin,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  constraint capture_not_empty check (length(title) + length(content) + length(reaction) + coalesce(length(source_url), 0) > 0),
  search tsvector generated always as (
    setweight(to_tsvector('english'::regconfig, coalesce(title, '') || ' ' || coalesce(source_title, '') || ' ' || coalesce(attribution, '')), 'A') ||
    setweight(to_tsvector('english'::regconfig, coalesce(reaction, '') || ' ' || coalesce(summary, '')), 'B') ||
    setweight(to_tsvector('english'::regconfig, coalesce(content, '') || ' ' || coalesce(transcript, '')), 'C')
  ) stored
);
create index captures_search_idx on captures using gin (search);
create index captures_created_idx on captures (created_at desc);
create index captures_kind_idx on captures (kind);
create trigger captures_touch before update on captures for each row execute function touch_updated_at();

create table tags (
  id    uuid primary key default gen_random_uuid(),
  name  citext not null unique check (name ~ '^[a-z0-9][a-z0-9 -]{0,39}$')
);

create table capture_tags (
  capture_id uuid not null references captures (id) on delete cascade,
  tag_id     uuid not null references tags (id) on delete cascade,
  primary key (capture_id, tag_id)
);
create index capture_tags_tag_idx on capture_tags (tag_id);

-- Voice notes, photos, PDFs. Stored in Postgres for now (small files, private, backed up with the DB).
-- Move to private Supabase Storage when files outgrow this.
create table attachments (
  id          uuid primary key default gen_random_uuid(),
  capture_id  uuid not null references captures (id) on delete cascade,
  filename    text not null check (length(filename) between 1 and 200),
  mime_type   text not null check (mime_type in (
                'audio/webm', 'audio/ogg', 'audio/mpeg', 'audio/mp4', 'audio/x-m4a', 'audio/wav',
                'image/jpeg', 'image/png', 'image/webp', 'image/gif', 'application/pdf', 'text/plain')),
  size_bytes  integer not null check (size_bytes between 1 and 4194304),
  data        bytea not null,
  created_at  timestamptz not null default now()
);
create index attachments_capture_idx on attachments (capture_id);

-- "Promote to Newsletter": an editorial entry linked to the capture. The capture itself is never modified.
alter table entries add column capture_id uuid references captures (id) on delete set null;
create unique index entries_capture_unique on entries (capture_id) where capture_id is not null;

alter table captures     enable row level security;
alter table tags         enable row level security;
alter table capture_tags enable row level security;
alter table attachments  enable row level security;

insert into _dash_migrations (name) values ('20261120000001_knowledge.sql');

alter table _dash_migrations enable row level security;

commit;
